<?php
return [
 'protection echoes message id and shape' => function () { [$c, $r] = call(api(), 'POST', '/v1/protection/sms', ['body' => 'hello', 'message_id' => 'm-1']); eq($c, 200); eq($r['message_id'], 'm-1'); eq($r['client_ref'], 'm-1'); eq($r['status'], 'ok'); check(isset($r['verdict'], $r['severity'], $r['scanner_verdict'], $r['evidence_items'], $r['show_warning'])); },
 'protection warns on phishing' => function () { [$c, $r] = call(api(), 'POST', '/v1/protection/sms', ['body' => 'تم إيقاف حسابك اضغط http://nbe-verify-login.top/a']); eq($r['show_warning'], true); },
 'protection no warning on safe' => function () { [$c, $r] = call(api(), 'POST', '/v1/protection/sms', ['body' => 'تمام']); eq($r['show_warning'], false); eq($r['verdict'], 'safe'); },
 'protection past deadline gives unknown timeout' => function () { $sc = scanner(['protectionDeadline' => -1.0]); $a = api(['protectionDeadline' => -1.0], $sc); [$c, $r] = call($a, 'POST', '/v1/protection/sms', ['body' => 'hello']); eq($r['status'], 'timeout'); eq($r['verdict'], 'unknown'); eq($r['show_warning'], true); },
 'protection failure is unknown never safe' => function () { $sc = scanner(); $sc->engines = new class(cfg()) extends P2\Engines { public function analyze(string $k, string $c, array $x): P2\EngineResult { throw new RuntimeException('boom'); } }; [$c, $r] = call(api([], $sc), 'POST', '/v1/protection/sms', ['body' => 'hello']); eq($r['status'], 'service_unavailable'); eq($r['verdict'], 'unknown'); },
 'protection validates input' => function () { foreach ([[], ['body' => ''], ['body' => 5], ['body' => 'a', 'message_id' => 5], ['body' => 'a', 'sender' => str_repeat('x', 100)]] as $b) eq(call(api(), 'POST', '/v1/protection/sms', $b)[0], 422); },
 'browser safe site may open' => function () { [$c, $r] = call(api(), 'POST', '/v1/browser/precheck', ['url' => 'https://example.com/']); eq($c, 200); eq($r['browser']['open_allowed'], true); eq($r['browser']['interstitial'], null); },
 'browser malicious has no proceed button' => function () { $bl = new class { public string $name = 'bl'; public function check(string $u): P2\IntelResult { return new P2\IntelResult('bl', 'confirmed', 'malicious'); } };
   [$c, $r] = call(api([], scanner([], null, null, null, [$bl])), 'POST', '/v1/browser/precheck', ['url' => 'http://x.example/']); eq($r['browser']['open_allowed'], false); eq($r['browser']['user_can_proceed'], false); eq($r['browser']['interstitial'], 'block_page'); },
 'browser suspicious warns but can proceed' => function () { [$c, $r] = call(api(), 'POST', '/v1/browser/precheck', ['url' => 'http://127.0.0.1/']); eq($r['browser']['interstitial'], 'warning_page'); eq($r['browser']['user_can_proceed'], true); eq($r['browser']['open_allowed'], false); },
 'browser unknown is not openable' => function () { [$c, $r] = call(api([], scanner([], new FakeWeb([], 200, 'timeout'))), 'POST', '/v1/browser/precheck', ['url' => 'http://a.example/']); eq($r['verdict'], 'unknown'); eq($r['browser']['open_allowed'], false); eq($r['browser']['interstitial'], 'unverified_notice'); },
 'browser bad url is 422' => fn() => eq(call(api(), 'POST', '/v1/browser/precheck', ['url' => ''])[0], 422),
 'browser invalid scheme gives unknown not open' => function () { [$c, $r] = call(api(), 'POST', '/v1/browser/precheck', ['url' => 'javascript:alert(1)']); eq($r['browser']['open_allowed'], false); },
];
